use serde_json::{json,Value};
use ss_core::cn::wps::et::ss::{calcchain::FormulaHelper::FormulaHelper,constant::RecogniseResult::RecogniseResult,formula::ptg::Ptg::Ptg,statemachine::RecogniseResultRl::Value as RValue};
use ss_core::org::apache::poi::ss::SpreadsheetVersion::SpreadsheetVersion;
fn bytes(text:&str)->Vec<u8>{(0..text.len()).step_by(2).map(|i|u8::from_str_radix(&text[i..i+2],16).unwrap()).collect()}
fn version(v:&Value)->SpreadsheetVersion{if v==97{SpreadsheetVersion::EXCEL97}else{SpreadsheetVersion::EXCEL2007}}
fn result(rs:&RecogniseResult)->Value{let Some(RValue::Number(n))=rs.getValue()else{panic!("expected original numeric RecogniseResult")};json!({"format":rs.getSuggestedNumfmt(),"builtin":rs.getBuiltInNumfmtIdx(),"date":rs.hasDateFlag(),"time":rs.hasTimeFlag(),"bits":format!("{:016x}",n.to_bits())})}
fn root()->std::path::PathBuf{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/formula-format-r0b30")}
#[test]
fn original_android_formula_suggested_format_and_shared_eligibility(){
    let p=root();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let mut rows=vec![];
    for expected in java["suggestions"].as_array().unwrap(){let input=&expected["input"];let b=bytes(input["hex"].as_str().unwrap());let ptgs=Ptg::readTokens(b.len()as i32,&b,version(&input["version"]));let mut row=json!({"input":input,"shared":FormulaHelper::fmlCanBeSharedfml(&ptgs)});let language=input["language"].as_str().map(util::org::apache::poi::util::LanguageType::LanguageType::valueOf);match std::panic::catch_unwind(||FormulaHelper::getFormulaSuggestedNumfmt(&ptgs,language)){Ok(rs)=>row["result"]=result(&rs),Err(e)=>{let message=e.downcast_ref::<&str>().map(|s|s.to_string()).or_else(||e.downcast_ref::<String>().cloned()).unwrap_or_default();assert!(message.contains("ArrayIndexOutOfBoundsException"),"{message}");row["exception"]=json!("ArrayIndexOutOfBoundsException");}}assert_eq!(row,*expected);rows.push(row);}
    std::fs::write(p.join("rust-suggestions.json"),serde_json::to_vec_pretty(&rows).unwrap()).unwrap();
}
#[test]
fn original_android_local_number_area_reference_and_break_scope(){
    use ss_core::cn::wps::moss::{app::{KmoBookApi::KmoBookApi,KmoLocale::KmoLocale},engine::grid::KmoCellData::KmoCellData};
    let p=root();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();KmoLocale::setLocale("zh_CN".into());kfc::cn::wps::kfc::numfmt::i18n::KmoLang::KmoLang::setLocale("zh_CN".into());let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let sheet=book.sheetAt(0);let s=sheet.borrow();let formats=["General","[$-D00041E]0","[$-2000401]0","[$-D00041E]0 ","0.00"];let mut xfs=vec![];for format in formats{let m=book.getXFManager().borrow();let index=m.cloneCellXF(15);let xf=m.getXF(index).unwrap();xf.setFormatIndex(0);xf.setNumFormat(Some(format.into()));xfs.push(index);}for r in 56..64{for c in 40..48{if(r+c)%4!=0{let data=KmoCellData{ixf:xfs[((r*3+c)%5)as usize],id:book.getCellValueStore().borrow_mut().newDoubleValue((r*100+c)as f64),..Default::default()};s.setCellData(r,c,&data);}}}
    let mut rows=vec![];for expected in java["local"].as_array().unwrap(){let input=&expected["input"];let b=bytes(input["hex"].as_str().unwrap());let ptgs=Ptg::readTokens__stream(b.len()as i32,&b,input["external"].as_bool().unwrap(),version(&input["version"]));let mut rs=RecogniseResult::fromValue(RValue::Number(0.0));rs.setSuggestedNumfmt__2(22);rs.setSuggestedNumfmt(Some("initial".into()));s.handleLocalNumber(&ptgs,&mut rs);let row=json!({"input":input,"result":result(&rs)});assert_eq!(row,*expected);rows.push(row);}std::fs::write(p.join("rust-local.json"),serde_json::to_vec_pretty(&rows).unwrap()).unwrap();
}
